import { describe, expect, it } from "vitest";
import { selectRoundingMethod } from "./index.js";

describe("getRoundingMethod", () => {
  it("rounds with truncate by default", () => {
    expect(selectRoundingMethod(undefined)(2.9)).toBe(2);
    expect(selectRoundingMethod(undefined)(1.5)).toBe(1);
    expect(selectRoundingMethod(undefined)(-3.9)).toBe(-3);
    expect(selectRoundingMethod(undefined)(-14.1)).toBe(-14);
  });

  it('allows to specify "trunc" rounding method', () => {
    expect(selectRoundingMethod("trunc")(2.9)).toBe(2);
    expect(selectRoundingMethod("trunc")(1.5)).toBe(1);
    expect(selectRoundingMethod("trunc")(-3.9)).toBe(-3);
    expect(selectRoundingMethod("trunc")(-14.1)).toBe(-14);
  });

  it('allows to specify "ceil" rounding method', () => {
    expect(selectRoundingMethod("ceil")(2.9)).toBe(3);
    expect(selectRoundingMethod("ceil")(1.5)).toBe(2);
    expect(selectRoundingMethod("ceil")(-3.9)).toBe(-3);
    expect(selectRoundingMethod("ceil")(-14.1)).toBe(-14);
  });

  it('allows to specify "floor" rounding method', () => {
    expect(selectRoundingMethod("floor")(2.9)).toBe(2);
    expect(selectRoundingMethod("floor")(1.5)).toBe(2);
    expect(selectRoundingMethod("floor")(-3.9)).toBe(-4);
    expect(selectRoundingMethod("floor")(-14.1)).toBe(-15);
  });

  it('allows to specify "round" rounding method', () => {
    expect(selectRoundingMethod("round")(2.9)).toBe(3);
    expect(selectRoundingMethod("round")(1.5)).toBe(2);
    expect(selectRoundingMethod("round")(-3.9)).toBe(-4);
    expect(selectRoundingMethod("round")(-14.1)).toBe(-14);
  });

  it("prevents negative zero", () => {
    expect(!isNegativeZero(selectRoundingMethod("trunc")(-0.01))).toBe(true);
    expect(!isNegativeZero(selectRoundingMethod("floor")(-0.0))).toBe(true);
    expect(!isNegativeZero(selectRoundingMethod("ceil")(-0.9))).toBe(true);
    expect(!isNegativeZero(selectRoundingMethod("round")(-0.1))).toBe(true);
  });
});

function isNegativeZero(x: number): boolean {
  return x === 0 && 1 / x < 0;
}

